insert into public.products(id,name,description,category,product_type,color,color_hex,image_url,details,fit,care) values ('core-oversized-tee','Core Oversized Tee','A generous silhouette. A quiet statement. The Core Tee brings a dropped shoulder and substantial cotton feel to your everyday rotation.','men','T-shirts','Washed Black','#343434','/assets/core-tee.webp','["Dropped shoulders and a relaxed silhouette","Soft washed finish","Understated TSUYO chest print"]','Oversized fit','Wash cold with similar colours. Turn inside out, air dry, and avoid ironing the print.') on conflict(id) do nothing;
