insert into public.products(id,name,description,category,product_type,color,color_hex,image_url,details,fit,care) values ('pump-cover-tee','Essential Pump Cover','From the first warm-up to the walk home. An easy oversized layer in a soft bone colour, with a substantial feel and minimal branding.','men','T-shirts','Bone','#d9d6cd','/assets/pump-cover.webp','["Roomy dropped shoulder shape","Bone colour with graphite chest print","Layer over your everyday training kit"]','Oversized fit','Wash cold, inside out, with similar colours. Air dry and avoid ironing the print.') on conflict(id) do nothing;
